    id: "croatia-otocac-cities-v2", "sights": {"de": [{"name": "Perin vrh", "text": "Der Berggipfel Perin vrh prägt die Landschaft nahe der Ortschaft Otočac. Wer die Höhe erklimmt, wird mit schönen Ausblicken auf die umliegende Lika-Region belohnt.", "category": "natural", "coords": [15.225236, 44.8436]}, {"name": "Inin vrh", "text": "Ein Gipfel in der Gegend von Otočac, der zur Gebirgslandschaft der Gespanschaft Lika-Senj gehört.", "category": "natural", "coords": [15.233433, 44.881684]}, {"name": "Poljički vrh", "text": "Ein Berggipfel in der unmittelbaren Umgebung der Stadt Otočac.", "category": "natural", "coords": [15.220516, 44.883182]}, {"name": "Rastik", "text": "Ein Gipfel bei Otočac, der bei Naturfreunden und Wanderern beliebt ist.", "category": "natural", "coords": [15.212382, 44.87994]}, {"name": "Milešnjak", "text": "Ein Berggipfel in der Region Lika, unweit der Stadt Otočac gelegen.", "category": "natural", "coords": [15.225922, 44.891211]}, {"name": "Gačanski park hrvatske memorije", "text": "Ein Gedenkpark in Otočac mit Steinkulpturen, die wichtige Symbole der Gacka-Region darstellen.", "category": "park", "coords": [15.236997, 44.869186]}, {"name": "Tvrđava Fortica", "text": "Die Überreste einer strategischen Festung aus dem 17. Jahrhundert auf einem Hügel über Otočac.", "category": "historical", "coords": [15.233907, 44.872759]}, {"name": "Gacka", "text": "Eine architektonisch bedeutende Brücke, die den Fluss Gacka in der Nähe von Otočac überquert.", "category": "landmark", "coords": [15.210793, 44.862499]}], "hu": [{"name": "Perin vrh", "text": "A Perin vrh hegycsúcs meghatározza az Otočac település közelében fekvő tájat. Aki felmászik a magaslatra, azt a környező Lika régió szép kilátása jutalmazza.", "category": "natural", "coords": [15.225236, 44.8436]}, {"name": "Inin vrh", "text": "Egy hegycsúcs Otocac környékén, amely Lika-Zengg megye hegyvidékéhez tartozik.", "category": "natural", "coords": [15.233433, 44.881684]}, {"name": "Poljički vrh", "text": "Egy hegycsúcs Otocac városának közvetlen közelében.", "category": "natural", "coords": [15.220516, 44.883182]}, {"name": "Rastik", "text": "Egy hegycsúcs Otocacnál, amely népszerű a természetjárók és túrázók körében.", "category": "natural", "coords": [15.212382, 44.87994]}, {"name": "Milešnjak", "text": "Egy hegycsúcs a Lika-régióban, nem messze Otocac városától.", "category": "natural", "coords": [15.225922, 44.891211]}, {"name": "Gačanski park hrvatske memorije", "text": "Emlékpark Otocacban kőszobrokkal, amelyek a Gacka-vidék fontos szimbólumait ábrázolják.", "category": "park", "coords": [15.236997, 44.869186]}, {"name": "Tvrđava Fortica", "text": "Egy 17. századi stratégiai erőd maradványai az Otocac feletti dombon.", "category": "historical", "coords": [15.233907, 44.872759]}, {"name": "Gacka", "text": "Egy építészetileg jelentős híd, amely a Gacka-folyót íveli át Otocac közelében.", "category": "landmark", "coords": [15.210793, 44.862499]}], "ro": [{"name": "Perin vrh", "text": "Vârful de munte Perin vrh caracterizează peisajul din apropierea localității Otočac. Cei care urcă la înălțime sunt recompensați cu priveliști frumoase asupra regiunii Lika din jur.", "category": "natural", "coords": [15.225236, 44.8436]}, {"name": "Inin vrh", "text": "Un vârf în zona Otočac, făcând parte din peisajul montan al cantonului Lika-Senj.", "category": "natural", "coords": [15.233433, 44.881684]}, {"name": "Poljički vrh", "text": "Un vârf muntos situat în imediata apropiere a orașului Otočac.", "category": "natural", "coords": [15.220516, 44.883182]}, {"name": "Rastik", "text": "Un vârf lângă Otočac, popular printre iubitorii de natură și drumeții.", "category": "natural", "coords": [15.212382, 44.87994]}, {"name": "Milešnjak", "text": "Un vârf muntos în regiunea Lika, situat nu departe de orașul Otočac.", "category": "natural", "coords": [15.225922, 44.891211]}, {"name": "Gačanski park hrvatske memorije", "text": "Un parc memorial în Otočac cu sculpturi în piatră ce reprezintă simboluri importante ale regiunii Gacka.", "category": "park", "coords": [15.236997, 44.869186]}, {"name": "Tvrđava Fortica", "text": "Rămășițele unei cetăți strategice din secolul al XVII-lea pe un deal deasupra orașului Otočac.", "category": "historical", "coords": [15.233907, 44.872759]}, {"name": "Gacka", "text": "Un pod semnificativ din punct de vedere arhitectural care traversează râul Gacka lângă Otočac.", "category": "landmark", "coords": [15.210793, 44.862499]}], "en": [{"name": "Perin vrh", "text": "The Perin vrh mountain peak characterizes the landscape near the town of Otočac. Those who climb to the top are rewarded with beautiful views of the surrounding Lika region.", "category": "natural", "coords": [15.225236, 44.8436]}, {"name": "Inin vrh", "text": "A peak in the Otočac area, part of the mountainous landscape of the Lika-Senj County.", "category": "natural", "coords": [15.233433, 44.881684]}, {"name": "Poljički vrh", "text": "A mountain peak located in the immediate vicinity of the town of Otočac.", "category": "natural", "coords": [15.220516, 44.883182]}, {"name": "Rastik", "text": "A peak near Otočac, popular among nature lovers and hikers.", "category": "natural", "coords": [15.212382, 44.87994]}, {"name": "Milešnjak", "text": "A mountain peak in the Lika region, located not far from the town of Otočac.", "category": "natural", "coords": [15.225922, 44.891211]}, {"name": "Gačanski park hrvatske memorije", "text": "A memorial park in Otočac featuring stone sculptures that represent important symbols of the Gacka region.", "category": "park", "coords": [15.236997, 44.869186]}, {"name": "Tvrđava Fortica", "text": "The remains of a 17th-century strategic fortress located on a hill above Otočac.", "category": "historical", "coords": [15.233907, 44.872759]}, {"name": "Gacka", "text": "An architecturally significant bridge spanning the Gacka River near Otočac.", "category": "landmark", "coords": [15.210793, 44.862499]}], "hr": [{"name": "Perin vrh", "text": "Planinski vrh Perin vrh oblikuje krajolik u blizini mjesta Otočac. Oni koji se popnu na visinu bit će nagrađeni lijepim pogledima na okolnu regiju Liku.", "category": "natural", "coords": [15.225236, 44.8436]}, {"name": "Inin vrh", "text": "Vrh na području Otočca koji je dio planinskog krajolika Ličko-senjske županije.", "category": "natural", "coords": [15.233433, 44.881684]}, {"name": "Poljički vrh", "text": "Planinski vrh koji se nalazi u neposrednoj blizini grada Otočca.", "category": "natural", "coords": [15.220516, 44.883182]}, {"name": "Rastik", "text": "Vrh pokraj Otočca pogodan za ljubitelje planinarenja i prirode.", "category": "natural", "coords": [15.212382, 44.87994]}, {"name": "Milešnjak", "text": "Planinski vrh u ličkom kraju smješten nedaleko od grada Otočca.", "category": "natural", "coords": [15.225922, 44.891211]}, {"name": "Gačanski park hrvatske memorije", "text": "Memorijalni park u Otočcu s kamenim klesancima koji simboliziraju povijest i baštinu Gacke.", "category": "park", "coords": [15.236997, 44.869186]}, {"name": "Tvrđava Fortica", "text": "Ostaci obrambene utvrde iz 17. stoljeća na uzvisini iznad grada Otočca.", "category": "historical", "coords": [15.233907, 44.872759]}, {"name": "Gacka", "text": "Značajan mostni objekt koji premošćuje rijeku Gacku u blizini Otočca.", "category": "landmark", "coords": [15.210793, 44.862499]}]},
