    id: "croatia-vukovar-v2-cities-v2", "sights": {"de": [{"name": "Park prirode Tikvara", "text": "Der Naturpark Tikvara ist ein geschütztes Gebiet an einem Altarm der Donau.", "category": "natural", "coords": [19.349716, 45.240823]}, {"name": "Stari vinski podrumi", "text": "Diese historischen Weinkeller in Ilok sind für ihre jahrhundertelange Tradition der Weinherstellung bekannt.", "category": "museum", "coords": [19.372089, 45.224056]}, {"name": "Plazha Tikvara", "text": "Der Strand Tikvara ist ein beliebter Bade- und Erholungsort am Ufer der Donau.", "category": "recreational", "coords": [19.379418, 45.234416]}, {"name": "Kurija Brnjaković", "text": "Die Kurie Brnjaković ist ein bedeutendes historisches Gebäude aus dem 18. Jahrhundert in Ilok.", "category": "castle", "coords": [19.375724, 45.224388]}, {"name": "Ladanjsko imanje Principovac", "text": "Das Landgut Principovac bietet Weinverkostungen, Sportanlagen und einen Panoramablick über Ilok.", "category": "recreational", "coords": [19.359268, 45.199941]}, {"name": "Vukovo", "text": "Dieser herrliche Aussichtspunkt liegt bei Ilok in Kroatien. Von Vukovo aus eröffnet sich den Gästen ein weiter Blick über die Donau und die angrenzenden Weinberge.", "category": "natural", "coords": [19.382196, 45.1996]}, {"name": "Most Ilok — Bačka Palanka", "text": "Diese Brücke über die Donau verbindet die Stadt Ilok in Kroatien mit Bačka Palanka in Serbien.", "category": "landmark", "coords": [19.401754, 45.233307]}], "hu": [{"name": "Park prirode Tikvara", "text": "A Tikvara natúrpark a Duna egyik holtága mentén fekvő védett természeti terület.", "category": "natural", "coords": [19.349716, 45.240823]}, {"name": "Stari vinski podrumi", "text": "Az újlaki történelmi borospincék évszázados borászati hagyományairól és minőségi borairól híresek.", "category": "museum", "coords": [19.372089, 45.224056]}, {"name": "Plazha Tikvara", "text": "A Tikvara strand népszerű fürdő- és pihenőhely a Duna partján.", "category": "recreational", "coords": [19.379418, 45.234416]}, {"name": "Kurija Brnjaković", "text": "A Brnjaković-kúria egy jelentős 18. századi történelmi épület Újlakon.", "category": "castle", "coords": [19.375724, 45.224388]}, {"name": "Ladanjsko imanje Principovac", "text": "A Principovac birtok borkóstolást, sportolási lehetőségeket és panorámás kilátást kínál Újlakra.", "category": "recreational", "coords": [19.359268, 45.199941]}, {"name": "Vukovo", "text": "Ez a csodálatos kilátó Ilok közelében, Horvátországban található. A Vukovóról a vendégek számára széles kilátás nyílik a Dunára és a szomszédos szőlőültetvényekre.", "category": "natural", "coords": [19.382196, 45.1996]}, {"name": "Most Ilok — Bačka Palanka", "text": "Ez a Dunán átívelő híd összeköti a horvátországi Újlakot a szerbiai Palánkával.", "category": "landmark", "coords": [19.401754, 45.233307]}], "ro": [{"name": "Park prirode Tikvara", "text": "Parcul natural Tikvara este o zonă naturală protejată situată de-a lungul unui braț mort al Dunării.", "category": "natural", "coords": [19.349716, 45.240823]}, {"name": "Stari vinski podrumi", "text": "Aceste crame istorice din Ilok sunt renumite pentru tradiția lor seculară în producția de vin.", "category": "museum", "coords": [19.372089, 45.224056]}, {"name": "Plazha Tikvara", "text": "Plaja Tikvara este un loc popular pentru înot și recreere pe malul Dunării.", "category": "recreational", "coords": [19.379418, 45.234416]}, {"name": "Kurija Brnjaković", "text": "Curia Brnjaković este o clădire istorică importantă din secolul al XVIII-lea situată în Ilok.", "category": "castle", "coords": [19.375724, 45.224388]}, {"name": "Ladanjsko imanje Principovac", "text": "Domeniul Principovac oferă degustări de vinuri, facilități sportive și vederi panoramice asupra orașului Ilok.", "category": "recreational", "coords": [19.359268, 45.199941]}, {"name": "Vukovo", "text": "Acest punct de belvedere magnific este situat lângă Ilok, în Croația. De pe Vukovo, oaspeții au o priveliște vastă peste Dunăre și podgoriile adiacente.", "category": "natural", "coords": [19.382196, 45.1996]}, {"name": "Most Ilok — Bačka Palanka", "text": "Acest pod peste Dunăre leagă orașul Ilok din Croația de Bačka Palanka din Serbia.", "category": "landmark", "coords": [19.401754, 45.233307]}], "en": [{"name": "Tikvara nature park", "text": "Tikvara Nature Park is a protected area located along an oxbow lake of the Danube.", "category": "natural", "coords": [19.349716, 45.240823]}, {"name": "Stari vinski podrumi", "text": "These historical wine cellars in Ilok are famous for their centuries-old winemaking tradition.", "category": "museum", "coords": [19.372089, 45.224056]}, {"name": "Beach Tikvara", "text": "Tikvara Beach is a popular swimming and recreation spot on the banks of the Danube.", "category": "recreational", "coords": [19.379418, 45.234416]}, {"name": "Kurija Brnjaković", "text": "The Brnjaković Curia is a significant 18th-century historical building in Ilok.", "category": "castle", "coords": [19.375724, 45.224388]}, {"name": "Ladanjsko imanje Principovac", "text": "The Principovac estate offers wine tasting, sports facilities, and panoramic views of Ilok.", "category": "recreational", "coords": [19.359268, 45.199941]}, {"name": "Vukovo", "text": "This magnificent viewpoint is located near Ilok in Croatia. From Vukovo, guests have a wide view over the Danube and the adjacent vineyards.", "category": "natural", "coords": [19.382196, 45.1996]}, {"name": "Most Ilok — Bačka Palanka", "text": "This bridge over the Danube connects the town of Ilok in Croatia with Bačka Palanka in Serbia.", "category": "landmark", "coords": [19.401754, 45.233307]}], "hr": [{"name": "Tikvara nature park", "text": "Park prirode Tikvara zaštićeno je područje smješteno uz dunavski rukavac.", "category": "natural", "coords": [19.349716, 45.240823]}, {"name": "Stari vinski podrumi", "text": "Ovi povijesni vinski podrumi u Iloku poznati su po svojoj stoljetnoj tradiciji vinarstva.", "category": "museum", "coords": [19.372089, 45.224056]}, {"name": "Beach Tikvara", "text": "Plaža Tikvara popularno je kupalište i rekreacijsko mjesto na obali Dunava.", "category": "recreational", "coords": [19.379418, 45.234416]}, {"name": "Kurija Brnjaković", "text": "Kurija Brnjaković značajna je povijesna građevina iz 18. stoljeća u Iloku.", "category": "castle", "coords": [19.375724, 45.224388]}, {"name": "Ladanjsko imanje Principovac", "text": "Ladanjsko imanje Principovac nudi degustacije vina, sportske sadržaje i panoramski pogled na Ilok.", "category": "recreational", "coords": [19.359268, 45.199941]}, {"name": "Vukovo", "text": "Ovaj veličanstveni vidikovac nalazi se u blizini Iloka u Hrvatskoj. S Vukova se gostima pruža širok pogled na Dunav i susjedne vinograde.", "category": "natural", "coords": [19.382196, 45.1996]}, {"name": "Most Ilok — Bačka Palanka", "text": "Most preko Dunava koji povezuje Ilok u Hrvatskoj i Bačku Palanku u Srbiji.", "category": "landmark", "coords": [19.401754, 45.233307]}]},
